import{_ as a,a0 as r,w as m,s,ao as g,I as p,x as t,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第四節 GNOME設置） | LCTT x X-CMD","titleTemplate":false,"description":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第四節 GNOME設置） | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第四節 GNOME設置） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第四節 GNOME設置） | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 4 - GNOME Settings","title":"一週 GNOME 之旅：品味它和 KDE 的是是非非（第四節 GNOME設置）","tag":"201508","desc":""},"relativePath":"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 4 - GNOME Settings.md","filePath":"[post].md"}'),l={name:"201508/20150716 A Week With GNOME As My Linux Desktop--What They Get Right & Wrong - Page 4 - GNOME Settings.md"};function h(w,e,E,d,O,_){const o=r("Link");return m(),s("div",null,[e[11]||(e[11]=g('<h1 id="一週-gnome-之旅-品味它和-kde-的是是非非-第四節-gnome設置" tabindex="-1">一週 GNOME 之旅：品味它和 KDE 的是是非非（第四節 GNOME設置） <a class="header-anchor" href="#一週-gnome-之旅-品味它和-kde-的是是非非-第四節-gnome設置" aria-label="Permalink to “一週 GNOME 之旅：品味它和 KDE 的是是非非（第四節 GNOME設置）”">​</a></h1><h3 id="設置" tabindex="-1">設置 <a class="header-anchor" href="#設置" aria-label="Permalink to “設置”">​</a></h3><p>在這我要挑一挑幾個特定 KDE 控制模組的毛病，大部分原因是因為相比它們的對手GNOME來説，糟糕得太可笑，實話説，真是悲哀。</p><p>第一個接招的？打印機。</p><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_printers1_show&amp;w=1920" alt=""></p><p>GNOME 在左，KDE 在右。你知道左邊跟右邊的打印程序有什麼區別嗎？當我在 GNOME 控制中心打開“打印機”時，程序窗口彈出來了，然後這樣就可以使用了。而當我在 KDE 系統設置打開“打印機”時，我得到了一條密碼提示。甚至我都沒能看一眼打印機呢，我就必須先交出 ROOT 密碼。</p><p>讓我再重複一遍。在今天這個有了 PolicyKit 和 Logind 的日子裏，對一個應該是 sudo 的操作，我依然被詢問要求 ROOT 的密碼。我安裝系統的時候甚至都沒設置 root 密碼。所以我必須跑到 Konsole 去，接着運行 &#39;sudo passwd root&#39; 命令，這樣我才能給 root 設一個密碼，然後我才能回到系統設置中的打印程序，再交出 root 密碼，然後僅僅是看一看哪些打印機可用。完成了這些工作後，當我點擊“添加打印機”時，我再次得到請求 ROOT 密碼的提示，當我解決了它後再選擇一個打印機和驅動時，我再次得到請求 ROOT 密碼的提示。僅僅是為了添加一個打印機到系統我就收到三次密碼請求！</p><p>而在 GNOME 下添加打印機，在點擊打印機程序中的“解鎖”之前，我沒有得到任何請求 SUDO 密碼的提示。整個過程我只被請求過一次，僅此而已。KDE，求你了……採用 GNOME 的“解鎖”模式吧。不到一定需要的時候不要發出提示。還有，不管是哪個庫，只要它允許 KDE 應用程序繞過 PolicyKit/Logind（如果有的話）並直接請求 ROOT 權限……那就把它封進箱裏吧。如果這是個多用户系統，那我要麼必須交出 ROOT 密碼，要麼我必須時時刻刻待命，以免有一個用户需要升級、更改或添加一個新的打印機。而這兩種情況都是完全無法接受的。</p><p>有還一件事……</p><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_printers2_show&amp;w=1920" alt=""></p><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_printers3_show&amp;w=1920" alt=""></p><p>這個問題問大家：怎麼樣看起來更簡潔？我在寫這篇文章時意識到：當有任何附加的打印機準備好時，Gnome 打印機程序會把過程做得非常簡潔，它們在左邊上放了一個豎直欄來列出這些打印機。而我在 KDE 中添加第二台打印機時，它突然增加出一個左邊欄來。而在添加之前，我腦海中已經有了一個恐怖的畫面，它會像圖片文件夾顯示預覽圖一樣直接在界面裏插入另外一個圖標。我很高興也很驚訝的看到我是錯的。但是事實是它直接“長出”另外一個從未存在的豎直欄，徹底改變了它的界面佈局，而這樣也稱不上“好”。終究還是一種令人困惑，奇怪而又不直觀的設計。</p><p>打印機説得夠多了……下一個接受我公開石刑的 KDE 系統設置是？多媒體，即 Phonon。</p><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_sound_show&amp;w=1920" alt=""></p><p>一如既往，GNOME 在左邊，KDE 在右邊。讓我們先看看 GNOME 的系統設置先……眼睛移動是從左到右，從上到下，對吧？來吧，就這樣做。首先：音量控制滑條。滑條中的藍色條與空條百分百清晰地消除了哪邊是“音量增加”的困惑。在音量控制條後馬上就是一個 On/Off 開關，用來開關靜音功能。Gnome 的再次得分在於靜音後能記住當前設置的音量，而在點擊音量增加按鈕取消靜音後能回到原來設置的音量中來。Kmixer，你個健忘的垃圾，我真的希望我能多討論你一下。</p><p>繼續！輸入輸出和應用程序的標籤選項？每一個應用程序的音量隨時可控？Gnome，每過一秒，我愛你越深。音量均衡選項、聲音配置、和清晰地標上標誌的“測試麥克風”選項。</p><p>我不清楚它能否以一種更乾淨更簡潔的設計實現。是的，它只是一個 Gnome 化的 Pavucontrol，但我想這就是重要的地方。Pavucontrol 在這方面幾乎完全做對了，Gnome 控制中心中的“聲音”應用程序的改善使它向完美更進了一步。</p><p>Phonon，該你上了。但開始前我想説：我 TM 看到的是什麼？！我知道我看到的是音頻設備的優先級列表，但是它呈現的方式有點太坑。還有，那些用户可能關心的那些東西哪去了？擁有一個優先級列表當然很好，它也應該存在，但問題是優先級列表屬於那種用户亂搞一兩次之後就不會再碰的東西。它還不夠重要，或者説不夠常用到可以直接放在正中間位置的程度。音量控制滑塊呢？對每個應用程序的音量控制功能呢？那些用户使用最頻繁的東西呢？好吧，它們在 Kmix 中，一個分離的程序，擁有它自己的配置選項……而不是在系統設置下……這樣真的讓“系統設置”這個詞變得有點用詞不當。</p><p><img src="http://www.phoronix.net/image.php?id=gnome-week-editorial&amp;image=gnome_week_network_show&amp;w=1920" alt=""></p><p>上面展示的 Gnome 的網絡設置。KDE 的沒有展示，原因就是我接下來要吐槽的內容了。如果你進入 KDE 的系統設置裏，然後點擊“網絡”區域中三個選項中的任何一個，你會得到一大堆的選項：藍牙設置、Samba 分享的默認用户名和密碼（説真的，“連通性（Connectivity）”下面只有兩個選項：SMB 的用户名和密碼。TMD 怎麼就配得上“連通性”這麼大的詞？），瀏覽器身份驗證控制（只有 Konqueror 能用……一個已經倒閉的項目），代理設置，等等……我的 wifi 設置哪去了？它們沒在這。哪去了？好吧，它們在網絡應用程序的設置裏面……而不是在網絡設置裏……</p><p>KDE，你這是要殺了我啊，你有“系統設置”當兇器，拿着它動手吧！</p><hr>',22)),p("p",null,[e[1]||(e[1]=t("via: ",-1)),i(o,{href:"http://www.phoronix.com/scan.php?page=article&item=gnome-week-editorial&num=4"},{default:n(()=>[...e[0]||(e[0]=[t("http://www.phoronix.com/scan.php?page=article&item=gnome-week-editorial&num=4",-1)])]),_:1})]),p("p",null,[e[4]||(e[4]=t("作者：Eric Griffith 譯者：",-1)),i(o,{href:"https://github.com/XLCYun"},{default:n(()=>[...e[2]||(e[2]=[t("XLCYun",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),i(o,{href:"https://github.com/wxy"},{default:n(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[8]||(e[8]=t("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),i(o,{href:"https://linux.cn/"},{default:n(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const T=a(l,[["render",h]]);export{N as __pageData,T as default};
